import re, os
F = 'inputs/CERTICOM-CHALLENGE-2009/challenge-2009_text.md'
L = open(F, encoding='utf-8').read().split('\n')
RED = [(1281, 1407), (2022, 2302)]
ANCH = {1451, 1452, 1489, 1490, 1532, 1533, 1583, 1584, 1614, 1615, 1644, 1645, 1823, 1824}
KW = re.compile(r'iterat|operat|step|machine|day|time|run|estimat|expect|rho|sqrt|solv|effort|work|year|hour|second|minute|mips|comput|speed|cpu|processor|pentium|2\s*\^\s*\{?\s*\d+\.\d|\d\s*[x×]\s*10\s*\^|10\*\*|e\+\d', re.I)
def view(a, b):
    for n in range(a, b + 1):
        s = L[n - 1]
        if any(x <= n <= y for x, y in RED) or n in ANCH:
            print(f'{n}: <redacted range: not displayed>'); continue
        if KW.search(s):
            print(f'{n}: <suppressed by work-estimate keyword mask>'); continue
        print(f'{n}: ' + re.sub(r'[0-9]', '#', s))
a, b = map(int, os.environ['WIN'].split('-'))
view(a, b)

