import math
from decimal import Decimal, getcontext
getcontext().prec = 60
LN2 = Decimal(2).ln()
OMEGA = 3            # PIN-OMEGA: the sentence after eq. (15), paper lines 1088-1091
OMEGA2 = 2           # eq. (16): sparse linear algebra constant omega' = 2 (line 1101)
def kval(n, m, rd): return n / m if rd == 'KR-A' else -(-n // m)
def A_float(n, m, rd):
    # log2 of m! * 2^(n - m k) * 2^k : eq. (15) with the per-system solve cost removed
    k = kval(n, m, rd)
    return math.log2(math.factorial(m)) + (n - m * k) + k
def C1_float(n, m, rd, D=4, reading='BS-n', om=OMEGA):
    base = n if reading == 'BS-n' else n * (m - 1)
    return A_float(n, m, rd) + D * om * math.log2(base)
def C1_dec(n, m, rd, D=4, om=OMEGA):
    k = Decimal(n) / Decimal(m) if rd == 'KR-A' else Decimal(-(-n // m))
    return (Decimal(math.factorial(m)).ln() / LN2) + (Decimal(n) - m * k) + k + D * om * (Decimal(n).ln() / LN2)
def C1_exactP(n, m, rd, om=OMEGA):
    # eq. (11) exact form P = 1 - exp(-2^(mk-n)/m!) in place of the approximation 2^(mk-n)/m!
    k = kval(n, m, rd)
    x = 2.0 ** (m * k - n) / math.factorial(m)
    return k + 4 * om * math.log2(n) - math.log2(-math.expm1(-x))
def C2(n, m, rd): return OMEGA2 * kval(n, m, rd)
def argmin(f, lo, hi):
    vals = [(f(m), m) for m in range(lo, hi + 1)]
    best = min(vals)
    runner = min(v for v in vals if v[1] != best[1])
    return best, runner
print('formula KR-A: log2 C1 = log2(m!) + n/m + 4*omega*log2(n); KR-B: log2 C1 = log2(m!) + (n - m*ceil(n/m)) + ceil(n/m) + 4*omega*log2(n); omega =', OMEGA)
res = {}
for n in (571, 283, 359):
    for rd in ('KR-A', 'KR-B'):
        (v60, m60), (r60v, r60m) = argmin(lambda m: C1_float(n, m, rd), 2, 60)
        (v30, m30), (r30v, r30m) = argmin(lambda m: C1_float(n, m, rd), 2, 30)
        vd = C1_dec(n, m60, rd)
        (ve, me), _ = argmin(lambda m: C1_exactP(n, m, rd), 2, 60)
        (va, ma), _ = argmin(lambda m: A_float(n, m, rd), 2, 60)
        m17 = math.sqrt(2 * math.log(2) * n / math.log(n))
        res[(n, rd)] = (v60, m60, v30, m30)
        print(f'n={n} {rd}: min_2..60 log2C1={v60:.6f} (decimal {vd:.9f}, |diff| {abs(float(vd) - v60):.1e}) at m={m60} interior={2 < m60 < 60} runner-up m={r60m} (+{r60v - v60:.6f})')
        print(f'    min_2..30 log2C1={v30:.6f} at m={m30} interior={2 < m30 < 30} runner-up m={r30m} (+{r30v - v30:.6f})')
        print(f'    stage-2 check at m={m60}: log2 C2 = 2k = {C2(n, m60, rd):.6f}; stage 1 dominates: {v60 > C2(n, m60, rd)}; margin {v60 - C2(n, m60, rd):.3f} bits')
        print(f'    sensitivity exact-P eq.(11): min {ve:.6f} at m={me} (delta {ve - v60:+.6f})')
        print(f'    localisation only, solve cost uncharged (A alone): min {va:.6f} at m={ma}')
        print(f'    eq.(17) comparison (not the optimiser): m ~ sqrt((2 ln 2) n / ln n) = {m17:.4f}')
print('PER-m CURVE n | m | KR-A log2C1 | KR-B log2C1 | KR-B k | stage2 KR-A | stage2 KR-B')
for n in (571, 283, 359):
    for m in range(2, 61):
        print(f'{n} | {m} | {C1_float(n, m, "KR-A"):.6f} | {C1_float(n, m, "KR-B"):.6f} | {-(-n // m)} | {C2(n, m, "KR-A"):.4f} | {C2(n, m, "KR-B"):.4f}')

import math, re, json
from decimal import Decimal, getcontext
getcontext().prec = 60
FI = open('inputs/FIPS186-4-BINARY-CURVES/fips186-4_text.md', encoding='utf-8').read().split('\n')
def dec_from(ns): return int(''.join(re.sub(r'[^0-9]', '', FI[n - 1]) for n in ns))
LN2 = Decimal(2).ln()
def lg(x): return Decimal(x).ln() / LN2
def pi_dec():
    def atan_inv(x):
        s, term, n, x2, sign = Decimal(0), Decimal(1) / x, 1, x * x, 1
        while term > Decimal(10) ** -65:
            s += sign * term / n; term /= x2; n += 2; sign = -sign
        return s
    return 16 * atan_inv(5) - 4 * atan_inv(239)
PI = pi_dec()
N = 571; OMEGA = 3; MSET = range(2, 31); DMAX = 64
ROWS = {'K-571': (dec_from([7023, 7025, 7027, 7029]), 571), 'B-571': (dec_from([7060, 7062, 7064, 7066]), 1)}
Q1 = {c: lg(PI * r / (4 * k)) / 2 for c, (r, k) in ROWS.items()}
for c in Q1: print('Q1USED', json.dumps({'row': c, 'q1': f'{Q1[c]:.10f}'}))
def A(m, kr):
    k = Decimal(N) / m if kr == 'KR-A' else Decimal(-(-N // m))
    return lg(math.factorial(m)) + (N - m * k) + k
W = {D: lg(sum(math.comb(N, d) for d in range(D + 1))) for D in range(0, DMAX + 1)}
def C(m, kr, rd, D, om=OMEGA):
    a = A(m, kr)
    if rd == 'BS-n': return a + D * om * lg(N)
    if rd == 'F4-dense': return a + D * om * lg(N * (m - 1))
    if rd == 'R-M': return a + om * (W[D] - W[4] + 4 * lg(N))
def slope(m, rd, om=OMEGA):
    return om * lg(N) if rd == 'BS-n' else om * lg(N * (m - 1))
mins = {}
for c in ROWS:
    q1 = Q1[c]
    for kr in ('KR-A', 'KR-B'):
        for rd in ('BS-n', 'F4-dense', 'R-M'):
            for m in MSET:
                Dint = next((D for D in range(4, DMAX + 1) if C(m, kr, rd, D) >= q1), None)
                near = [D for D in range(4, DMAX + 1) if abs(C(m, kr, rd, D) - q1) < Decimal('1e-6')]
                rec = {'row': c, 'm': m, 'reading': rd, 'kr': kr, 'omega': OMEGA, 'D_int': Dint if Dint is not None else 'none<=64',
                       'C4_minus_Q1': f'{C(m, kr, rd, 4) - q1:.6f}', 'near_equality_D': near}
                if rd != 'R-M':
                    root = (q1 - A(m, kr)) / slope(m, rd)
                    rec['root_unconstrained'] = f'{root:.6f}'
                    rec['D_real'] = (f'{root:.2f}' if 4 <= root <= DMAX else ('none: C(4) > Q1' if root < 4 else 'none<=64'))
                    fl = (float(q1) - float(A(m, kr))) / float(slope(m, rd))
                    rec['float_check_abs_diff'] = f'{abs(fl - float(root)):.1e}'
                else:
                    rec['D_real'] = 'n/a (R-M defined at integer D only)'
                print('Q3ROW', json.dumps(rec))
                key = (c, rd, kr)
                if Dint is not None and (key not in mins or Dint < mins[key][0]): mins[key] = (Dint, [m])
                elif Dint is not None and Dint == mins[key][0]: mins[key][1].append(m)
for (c, rd, kr), (d, ms) in mins.items():
    print('Q3MIN', json.dumps({'row': c, 'reading': rd, 'kr': kr, 'omega': OMEGA, 'min_D_int_over_m': d, 'attained_at_m': ms}))

