import math, re, json
from decimal import Decimal, getcontext
getcontext().prec = 60
FI = open('inputs/FIPS186-4-BINARY-CURVES/fips186-4_text.md', encoding='utf-8').read().split('\n')
def dec_from(ns): return int(''.join(re.sub(r'[^0-9]', '', FI[n - 1]) for n in ns))
LN2 = Decimal(2).ln()
def lg(x): return Decimal(x).ln() / LN2
PI = Decimal('3.14159265358979323846264338327950288419716939937510582097494')
N = 571; OM = 3
Q1 = {'K-571': lg(PI * dec_from([7023, 7025, 7027, 7029]) / (4 * 571)) / 2, 'B-571': lg(PI * dec_from([7060, 7062, 7064, 7066]) / 4) / 2}
def kk(n, m, kr): return Decimal(n) / m if kr == 'KR-A' else Decimal(-(-n // m))
def A(n, m, kr, exactP=False):
    k = kk(n, m, kr)
    if not exactP: return lg(math.factorial(m)) + (n - m * k) + k
    x = float(2 ** (float(m * k - n))) / math.factorial(m)
    return k - Decimal(math.log2(-math.expm1(-x)))
W = {D: lg(sum(math.comb(N, d) for d in range(D + 1))) for D in range(65)}
def C(m, kr, rd, D, q_exactP=False, varcount=False):
    a = A(N, m, kr, q_exactP)
    if rd == 'BS-n': return a + D * OM * lg(N)
    if rd == 'F4-dense':
        nv = N * (m - 2) + m * int(kk(N, m, 'KR-B')) if (varcount and kr == 'KR-B') else (N * (m - 2) + m * kk(N, m, kr) if varcount else N * (m - 1))
        return a + D * OM * lg(nv)
    return a + OM * (W[D] - W[4] + 4 * lg(N))
def Dint(q1, **kw): return next((D for D in range(4, 65) if C(q1=None, **kw) >= q1), None) if False else None
def thr(q1, m, kr, rd, **kw):
    Di = next((D for D in range(4, 65) if C(m, kr, rd, D, **kw) >= q1), None)
    Dr = None
    if rd != 'R-M':
        c4, c5 = C(m, kr, rd, 4, **kw), C(m, kr, rd, 5, **kw)
        Dr = 4 + (q1 - c4) / (c5 - c4)
    return Di, Dr
for label, kw, q1mode in [('Q1 rounded to 4 dp', {}, 'round4'), ('exact eq. (11) probability', {'q_exactP': True}, 'full'), ('F4-dense with the exact variable count n(m-2)+mk', {'varcount': True}, 'full')]:
    ch_int, maxdr, ch_dr2 = [], Decimal(0), 0
    for row in Q1:
        q1b = Q1[row]; q1s = q1b.quantize(Decimal('0.0001')) if q1mode == 'round4' else q1b
        for kr in ('KR-A', 'KR-B'):
            for rd in (('F4-dense',) if 'varcount' in kw else ('BS-n', 'F4-dense', 'R-M')):
                for m in range(2, 31):
                    b = thr(q1b, m, kr, rd); s = thr(q1s, m, kr, rd, **kw)
                    if b[0] != s[0]: ch_int.append((row, kr, rd, m, b[0], s[0]))
                    if b[1] is not None and b[1] >= 4:
                        d = abs(b[1] - s[1]); maxdr = max(maxdr, d)
                        if f'{b[1]:.2f}' != f'{s[1]:.2f}': ch_dr2 += 1
    print(f'Q3 SENSITIVITY [{label}]: D_int changes: {ch_int if ch_int else "none"}; max |dD_real| = {maxdr:.6f}; D_real 2-dp changes: {ch_dr2}')
print('Q2 LOCALISATION ONLY, rejected mixed reading KR-C (P taken as 1/m!, k = ceil(n/m) in 2^k): log2 C1 = log2(m!) + ceil(n/m) + 12 log2 n')
for n in (571, 283, 359):
    v = [(lg(math.factorial(m)) + (-(-n // m)) + 4 * OM * lg(n), m) for m in range(2, 61)]
    b = min(v); v30 = min(x for x in v if x[1] <= 30)
    print(f'  n={n}: min {b[0]:.6f} at m={b[1]} (2..30: {v30[0]:.6f} at m={v30[1]})')

