import math, re, json
from decimal import Decimal, getcontext
getcontext().prec = 60
FI = open('inputs/FIPS186-4-BINARY-CURVES/fips186-4_text.md', encoding='utf-8').read().split('\n')
def dec_from(ns): return int(''.join(re.sub(r'[^0-9]', '', FI[n - 1]) for n in ns))
LN2 = Decimal(2).ln()
def lg(x): return Decimal(x).ln() / LN2
def pi_dec():
    def atan_inv(x):
        s, term, n, x2, sign = Decimal(0), Decimal(1) / x, 1, x * x, 1
        while term > Decimal(10) ** -65:
            s += sign * term / n; term /= x2; n += 2; sign = -sign
        return s
    return 16 * atan_inv(5) - 4 * atan_inv(239)
PI = pi_dec()
N = 571; OM = 3
Q1 = {'K-571': lg(PI * dec_from([7023, 7025, 7027, 7029]) / (4 * 571)) / 2, 'B-571': lg(PI * dec_from([7060, 7062, 7064, 7066]) / 4) / 2}
def kk(n, m, kr): return Decimal(n) / m if kr == 'KR-A' else Decimal(-(-n // m))
def A(n, m, kr, expP=False):
    k = kk(n, m, kr)
    if not expP: return lg(math.factorial(m)) + (n - m * k) + k
    x = (Decimal(2) ** (m * k - n)) / math.factorial(m)
    return k - lg(1 - (-x).exp())
W = {D: lg(sum(math.comb(N, d) for d in range(D + 1))) for D in range(65)}
def C(m, kr, rd, D, expP=False, varcount=False):
    a = A(N, m, kr, expP)
    if rd == 'BS-n': return a + D * OM * lg(N)
    if rd == 'F4-dense': return a + D * OM * lg(N * (m - 2) + m * kk(N, m, kr) if varcount else N * (m - 1))
    return a + OM * (W[D] - W[4] + 4 * lg(N))
def thr(q1, m, kr, rd, **kw):
    Di = next((D for D in range(4, 65) if C(m, kr, rd, D, **kw) >= q1), None)
    Dr = None
    if rd != 'R-M':
        c4, c5 = C(m, kr, rd, 4, **kw), C(m, kr, rd, 5, **kw)
        Dr = 4 + (q1 - c4) / (c5 - c4)
    return Di, Dr
for label, kw, rds in [('exponential form of eq. (11)', {'expP': True}, ('BS-n', 'F4-dense', 'R-M')), ('F4-dense exact variable count n(m-2)+mk', {'varcount': True}, ('F4-dense',))]:
    nint, maxd, n2 = 0, Decimal(0), 0
    for row in Q1:
        for kr in ('KR-A', 'KR-B'):
            for rd in rds:
                for m in range(2, 31):
                    b = thr(Q1[row], m, kr, rd); s = thr(Q1[row], m, kr, rd, **kw)
                    if b[0] != s[0]:
                        nint += 1; print('Q0SENS_DINT', json.dumps({'alt': label, 'row': row, 'kr': kr, 'reading': rd, 'm': m, 'pinned': b[0], 'alt_value': s[0]}))
                    if b[1] is not None and b[1] >= 4:
                        maxd = max(maxd, abs(b[1] - s[1]))
                        if f'{b[1]:.2f}' != f'{s[1]:.2f}':
                            n2 += 1; print('Q0SENS_DREAL2DP', json.dumps({'alt': label, 'row': row, 'kr': kr, 'reading': rd, 'm': m, 'pinned_D_real': f'{b[1]:.6f}', 'alt_D_real': f'{s[1]:.6f}'}))
    print('Q0SENS_SUM', json.dumps({'alt': label, 'D_int_changes': nint, 'max_abs_dD_real': f'{maxd:.6f}', 'D_real_2dp_changes': n2}))

